            values.append(left - right)
        elif operator == '*':
            values.append(left * right)
        elif operator == '/':
            if right == 0:
                raise ValueError("Division by zero")
            values.append(left / right)

    def greater_precedence(op1, op2):
        return precedence[op1] > precedence[op2]

    operators = []
    values = []
    i = 0
    while i < len(tokens):
        token = tokens[i]
        if token.isdigit():
            values.append(int(token))
